/* El idioma escogido se queda para la siguiente pestana y para manana
   (localStorage), no solo para esta pestana (seccion 101): el consultor
   de Brasil picaba la bandera cada vez que abria la consola. La pestana
   manda si ya escogio algo distinto en ella. */
export function idiomaGuardado() {
  try {
    const guardado = sessionStorage.getItem(LLAVE) || localStorage.getItem(LLAVE);
    if (TEXTOS[guardado]) return guardado;
  } catch { /* sin almacen se usa el de siempre */ }
  return null;
}

export function idioma() {
  return idiomaGuardado() || "es";
}

export function ponerIdioma(codigo) {
  try { sessionStorage.setItem(LLAVE, codigo); } catch { /* nada */ }
  try { localStorage.setItem(LLAVE, codigo); } catch { /* nada */ }
}

/* La clave se busca en el idioma puesto y, si falta, en espanol. */
export function t(clave) {
  const actual = TEXTOS[idioma()] || {};
  if (clave in actual) return actual[clave];
  return TEXTOS.es[clave] !== undefined ? TEXTOS.es[clave] : clave;
}

export function nombreIdioma(codigo = idioma()) {
  const i = IDIOMAS.find(x => x.codigo === codigo);
  return i ? i.nombre : codigo;
}
